prompt --application/shared_components/user_interface/templates/region/freshness_frame
begin
wwv_flow_imp_shared.create_plug_template(
 p_id=>wwv_flow_imp.id(610227657755817111)
,p_layout=>'TABLE'
,p_template=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<section class="amc-TFreshnessFrame #REGION_CSS_CLASSES#" id="#REGION_STATIC_ID#" #REGION_ATTRIBUTES# aria-labelledby="#REGION_STATIC_ID#_heading" data-amc-label-updated="Updated %0" data-amc-label-now="just now" data-amc-label-stale="Out of date" data-amc-label-stale-announce="The data in this region may be out of date." data-amc-label-refreshed="Data refreshed." data-amc-label-refreshing="Refreshing">',
'  <span class="amc-TFreshnessFrame-edge" aria-hidden="true"><span class="amc-TFreshnessFrame-fuse"></span></span>',
'  <div class="amc-TFreshnessFrame-surface">',
'    <header class="amc-TFreshnessFrame-header">',
'      <span class="amc-TFreshnessFrame-icon fa #ICON_CSS_CLASSES#" aria-hidden="true"></span>',
'      <h2 class="amc-TFreshnessFrame-title" id="#REGION_STATIC_ID#_heading">#TITLE#</h2>',
'      <div class="amc-TFreshnessFrame-status" hidden>',
'        <span class="amc-TFreshnessFrame-dot" aria-hidden="true"></span>',
'        <span class="amc-TFreshnessFrame-flag"></span>',
'        <time class="amc-TFreshnessFrame-age"></time>',
'        <button type="button" class="t-Button t-Button--small amc-TFreshnessFrame-refresh" hidden><span class="amc-TFreshnessFrame-refreshIcon fa fa-refresh" aria-hidden="true"></span><span class="amc-TFreshnessFrame-refreshLabel">Refresh</span></button>',
'      </div>',
'      <div class="amc-TFreshnessFrame-actions">#HELP##EDIT##CHANGE##COPY##DELETE##CREATE#</div>',
'    </header>',
'    <div class="amc-TFreshnessFrame-body">#BODY##SUB_REGIONS#</div>',
'    <footer class="amc-TFreshnessFrame-footer">#PREVIOUS##CLOSE##NEXT#</footer>',
'    <p class="amc-TFreshnessFrame-live" role="status" aria-live="polite"></p>',
'  </div>',
'</section>'))
,p_page_plug_template_name=>'AMC Freshness Frame'
,p_internal_name=>'AMC_TPL_FRESHNESS_FRAME'
,p_javascript_file_urls=>'#APP_FILES#amc-templates/amc-tpl-freshness-frame.js'
,p_css_file_urls=>'#APP_FILES#amc-templates/amc-tpl-freshness-frame.css'
,p_theme_id=>42
,p_default_template_options=>'amc-TFreshnessFrame--stale5'
,p_default_label_alignment=>'RIGHT'
,p_default_field_alignment=>'LEFT'
,p_translate_this_template=>'N'
,p_template_comment=>'Time-aware region template. The data time is the page load, or an ISO timestamp in a data-amc-updated attribute on the region (Custom Attributes, for example data-amc-updated="&P1_LOADED_AT.") or on any element inside the body, such as a hidden span in the report with the time the rows were loaded, so a report filled by a nightly job shows its real age. The header shows Updated just now, then the age in the page language through Intl.RelativeTimeFormat, with the exact time as a tooltip on a time element. A fuse along the top edge burns from full to empty over the threshold, its glow fading and its color moving from the success to the warning palette color; one timer for all regions updates every 10 seconds and does nothing while the tab is hidden. At the threshold (5 minutes by default; template options 1, 5 or 15 minutes, or a data-amc-stale-seconds Custom Attribute) the frame turns to an Out of date state: hatched warning edge, warning ring, flag text, a polite announcement, and a Refresh button when apex.region(staticId).refresh exists. Refresh marks the body aria-busy and everything resets on apexafterrefresh, also after refreshes started by Dynamic Actions, which re-read data-amc-updated from the new content. Auto refresh when stale refreshes once per stale period, only while the tab is visible. English strings to translate, on the section element in the template or per region as Custom Attributes: data-amc-label-updated Updated %0, data-amc-label-now just now, data-amc-label-stale Out of date, data-amc-label-stale-announce The data in this region may be out of date., data-amc-label-refreshed Data refreshed., data-amc-label-refreshing Refreshing, and the Refresh button label in the template. Under reduced motion the fuse steps instead of gliding and nothing pulses or spins, but every state still changes; in forced-colors mode the stale state uses a double border. Without JavaScript the region is a plain frame. JavaScript API: amcTplFreshnessFrame.refresh(element), reset(element) and state(element).'
);
end;
/
